# owner: platform
"""Weekly timesheet rows built from a list of shifts."""

from typing import Dict, List, Tuple

from hourglass.models import Shift

Tally = Dict[str, Tuple[int, int]]

def _tally(shifts: List[Shift]) -> Tally:
    """Shift count and minutes for each worker."""
    tally: Tally = {}
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("blank worker name")
        count, mins = tally.get(shift.worker, (0, 0))
        mins += shift.span.minutes
        tally[shift.worker] = (count + 1, mins)
    return tally

def _row(name: str, count: int, mins: int) -> str:
    hours = f"{mins / 60:.1f}"
    return f"{name}: {count} shifts, {hours} hours"

def _order(tally: Tally) -> List[str]:
    key = lambda name: (-tally[name][1], name)
    return sorted(tally, key=key)

# ---
def timesheet_rows(shifts: List[Shift]) -> List[str]:
    """One line per worker, busiest first."""
    if not shifts:
        raise ValueError("no shifts to total")
    tally = _tally(shifts)
    names = _order(tally)
    return [_row(name, *tally[name]) for name in names]

