# owner: platform
import unittest

from hourglass.models import Shift, Span
from hourglass.timesheet import timesheet_rows

def make_shift(worker, begin, finish, day="mon"):
    return Shift(worker, day, Span(begin, finish))

class TimesheetTests(unittest.TestCase):
    def setUp(self):
        self.rows = timesheet_rows([
            make_shift("Brisa", 540, 600),
            make_shift("Omar", 540, 780),
            make_shift("Brisa", 540, 600, "tue"),
        ])

    def test_busiest_first(self):
        self.assertEqual(self.rows[0][:4], "Omar")

    def test_row_text(self):
        self.assertEqual(
            self.rows[1], "Brisa: 2 shifts, 2.0 hours"
        )

    def test_one_decimal(self):
        rows = timesheet_rows([make_shift("Ana", 0, 100)])
        self.assertEqual(rows, ["Ana: 1 shifts, 1.7 hours"])

    def test_ties_by_name(self):
        rows = timesheet_rows([
            make_shift("Zed", 0, 60),
            make_shift("Amy", 0, 60),
        ])
        self.assertTrue(rows[0].startswith("Amy"))

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            timesheet_rows([])

    def test_blank_worker(self):
        with self.assertRaises(ValueError):
            timesheet_rows([make_shift("  ", 0, 60)])
